import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"Autoridad y autenticación en colaboración","description":"","frontmatter":{"title":"Autoridad y autenticación en colaboración","docId":"developer.collaboration","translationKey":"developer.collaboration","locale":"es","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"fb71673a581e923e3c02ae401a46937b007f9919690ca020d22c27b370b6c61d","translationRevision":"1067c9a16b3b87c09699da32141cd1629328938986b2f18276388c2a2d69848f","order":190},"headers":[],"relativePath":"es/developer/collaboration.md","filePath":"es/developer/collaboration.md","lastUpdated":1795727787000}`),a={name:`es/developer/collaboration.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="collaboration-authority-and-authentication" tabindex="-1">Autoridad y autenticación en colaboración <a class="header-anchor" href="#collaboration-authority-and-authentication" aria-label="Permalink to “Autoridad y autenticación en colaboración”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objetivo y requisitos”">​</a></h2><p>Permite que un dispositivo aprobado inspeccione o realice una operación acotada en un host existente. Usa un perfil de prueba del propietario, una compilación con soporte remoto y transporte configurado. Acceso a cuenta, equipo Cloud, propiedad local y sesión delegada directa son autoridades distintas.</p><h2 id="establish-the-trust-chain" tabindex="-1">Establecer la cadena de confianza <a class="header-anchor" href="#establish-the-trust-chain" aria-label="Permalink to “Establecer la cadena de confianza”">​</a></h2><p>La administración local <code>collaboration.*</code> controla configuración, invitaciones, solicitudes, identidades, permisos, sesiones y auditoría. Descubre sus esquemas antes de configurar escucha o crear credenciales:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> collaboration.configure</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> collaboration.invites.create</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> collaboration.status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span></span></code></pre></div><p>Una invitación inicia el emparejamiento, sin conceder autoridad de negocio. La aprobación crea sesión y permisos correspondientes. HTTPS directo exige certificados válidos o confianza nativa fijada explícitamente. Tokens nativos y cookies de navegador tienen límites diferentes. <code>collaboration.hello</code> vincula protocolo, instancia, identidad, sesión, revisión de permisos, capacidades y límites negociados.</p><h2 id="authorize-each-operation" tabindex="-1">Autorizar cada operación <a class="header-anchor" href="#authorize-each-operation" aria-label="Permalink to “Autorizar cada operación”">​</a></h2><p>Cada método remoto admitido debe superar lista permitida, capacidad, restricciones de recursos y comprobaciones de sesión actual. Deshabilitar/borrar workflows utiliza metadatos duraderos con comparación de revisión. Los ajustes de puntos son aditivos y tienen límites propios. Las lecturas remotas de automatización son resúmenes cerrados; guardar borradores desactivados de su autor no les concede autoridad ejecutable del propietario.</p><p>Revisión/adopción y aprobación comprobada vinculan definiciones, dependencias y procedencia actuales. Un manifiesto de vista previa sirve para inspección, no como token de ejecución. Revalida permisos y recursos en los límites de ejecución; la identidad del transporte no es autorización permanente.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Resultado esperado y estado”">​</a></h2><p>La colaboración directa nativa implementa lecturas acotadas, mutaciones duraderas seleccionadas y recuperación limitada. Equipos/relay Cloud tienen adaptadores propios; su recorrido de lectura documentado no debe presentarse como moderación o ejecución completa de borradores. Efectos delegados restantes, otras escrituras y aceptación entre varios equipos siguen experimentales. Consulta <a href="./remote-client.html">clientes remotos</a> y <a href="./cloud.html">Cloud</a>.</p><h2 id="recover-and-verify" tabindex="-1">Recuperación y verificación <a class="header-anchor" href="#recover-and-verify" aria-label="Permalink to “Recuperación y verificación”">​</a></h2><p>Ante revocación o cambio de identidad, detén suscripciones y elimina proyecciones privadas. Usa <code>collaboration.subscribe</code>, <code>snapshot</code> y <code>resume</code> según dominios negociados y cursores vigentes. Resuelve el identificador original ante una confirmación incierta. No repitas un borrado con otro identificador ni restaures autoridad desde un recibo antiguo. El <a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-collaboration/src" target="_blank" rel="noreferrer">código de autorización</a> y la política del registro definen el límite; superar TLS no prueba autorización.</p><h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Detalles de operación”">​</a></h2><p>Secuencia Teams: registra dispositivo, emite/acepta invitación o solicitud, aprueba y haz que el host confirme la revisión actual del permiso nativo. <code>pendingHost</code> indica ese paso pendiente. Una revisión nueva invalida la confirmación anterior; recarga ante expectedRevision caducada. Aceptación nativa exige snapshot reciente, host/dispositivo activos, permiso activo y confirmedRevision igual a revision. La UI expone paneles host/unión y aprobaciones disponibles; confirmación nativa es contrato API, no botón prometido en todo build.</p><p>Conversión heredada cerrada: observer lee live/workflows/puntos/competición/automatización/resultados; moderator añade ajustar puntos, toggles workflow/automatización y gestión de competición; automationEditor añade edición a las lecturas. Ningún preset implica scripts arbitrarios, efectos externos ni delegación reutilizable. <code>nativeGrant</code> explícito exige rol <code>custom</code>; restringe recursos, efectos y delta allí. Tipo de cliente nativo: solo <code>desktop</code> o <code>agent</code>. Políticas incompatibles fallan sin ampliar derechos. Diagnostica pairing, confirmación, revisión y transporte por separado.</p>`,17)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};